{
  "commonPhenomenon": "通道查单显示支付成功，但平台侧未检测到回调处理痕迹，导致资金状态不一致。",
  "facts": [
    {
      "statement": "主动查询（QUERY）显示支付成功。",
      "evidenceIds": [
        "E-010"
      ]
    },
    {
      "statement": "本地回调入口没有相应的处理痕迹。",
      "evidenceIds": [
        "E-010"
      ]
    }
  ],
  "differences": [
    {
      "description": "通道侧状态为成功，与平台侧缺失回调处理记录存在差异。",
      "evidenceIds": [
        "E-010"
      ]
    }
  ],
  "possibleExplanations": [
    {
      "hypothesis": "通道已发送回调通知，但因网络故障或超时导致平台未收到。",
      "evidenceIds": [
        "E-010"
      ],
      "verification": "检查通道侧的回调投递日志和重试记录，确认是否曾向平台地址发送请求及返回结果。"
    },
    {
      "hypothesis": "平台收到了回调通知，但因验签失败、格式错误或业务逻辑异常导致处理中断且未留痕。",
      "evidenceIds": [
        "E-010"
      ],
      "verification": "排查平台网关及应用层的访问日志、错误日志，查找是否有针对该订单号的入站请求及后续的错误堆栈。"
    },
    {
      "hypothesis": "通道侧虽显示成功，但实际并未触发回调机制或配置了错误的回调地址。",
      "evidenceIds": [
        "E-010"
      ],
      "verification": "核对商户在通道后台配置的回调URL是否正确，并联系通道客服确认该笔交易是否配置了异步通知。"
    }
  ],
  "checkSteps": [
    "获取通道侧该笔交易的完整回调投递日志，确认发送时间、目标URL及HTTP响应码。",
    "检索平台侧所有接收到的回调请求日志，包括Webhook入口、防火墙拦截日志及应用层日志。",
    "比对通道交易号与平台订单号，确保是同一笔交易。",
    "若发现平台有接收记录但无处理痕迹，分析当时的系统负载、数据库锁或代码异常日志。",
    "若通道无发送记录，检查通道配置及商户签约状态。"
  ],
  "missingInformation": [
    "通道侧具体的回调投递记录（发送时间、状态码、响应内容）。",
    "平台侧网关及应用层的详细入站请求日志。",
    "当前平台中该订单的实际资金状态（processing还是其他）。",
    "商户侧是否收到了任何来自平台的通知。"
  ],
  "knowledgeCitations": [
    "lost-callback"
  ],
  "knowledgeOmissionReason": null
}
